<?php $activeMenu='router';$routerView='routing';require_once __DIR__.'/../includes/sidebar.php'; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Routing - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><style>body{margin:0}.page{margin-left:220px;padding:32px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.title{font-size:28px;font-weight:700}.sub,.muted{color:#66758d}.btn{border:1px solid #d7e0ec;background:#fff;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.primary{background:#087cff;color:#fff;border-color:#087cff}.card{background:#fff;border:1px solid #dce4ef;border-radius:14px;overflow:hidden}.bar{padding:16px 20px;border-bottom:1px solid #e4e9f0;display:flex;justify-content:space-between}.wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:13px 15px;border-bottom:1px solid #edf1f6;text-align:left;font-size:13px}th{font-size:11px;text-transform:uppercase;color:#61718a;background:#f7f9fc}.badge{padding:5px 9px;border-radius:99px;font-size:11px;font-weight:700}.up{background:#dff6e9;color:#08774e}.down{background:#fde5e5;color:#b42318}.notice{padding:18px;color:#66758d}@media(max-width:800px){.page{margin-left:0;padding:20px}.head{align-items:flex-start;flex-direction:column;gap:12px}}</style></head><body><main class="page"><div class="head"><div><div class="title">Routing</div><div class="sub">Routing table MikroTik secara realtime.</div></div><button class="btn primary" id="refresh">↻ Refresh</button></div><div class="card"><div class="bar"><strong id="router">Router</strong><span class="muted" id="updated">Belum diperbarui</span></div><div class="wrap"><table><thead><tr><th>Destination</th><th>Gateway</th><th>Interface</th><th>Distance</th><th>Table</th><th>Status</th><th>Type</th></tr></thead><tbody id="rows"><tr><td colspan="7" class="notice">Memuat routing...</td></tr></tbody></table></div></div></main><script>const rows=document.getElementById('rows'),router=document.getElementById('router'),updated=document.getElementById('updated'),refresh=document.getElementById('refresh');const esc=v=>String(v??'-').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));async function load(){refresh.disabled=true;try{const r=await fetch('../api/router_routes.php?nocache='+Date.now(),{cache:'no-store'}),d=await r.json();if(d.status!=='online')throw Error(d.message||'Router offline');router.textContent=d.router||'Router';rows.innerHTML=(d.routes||[]).map(x=>`<tr><td><b>${esc(x.dst)}</b></td><td>${esc(x.gateway)}</td><td>${esc(x.interface)}</td><td>${esc(x.distance)}</td><td>${esc(x.routing_mark)}</td><td><span class="badge ${x.active&&!x.disabled?'up':'down'}">${x.disabled?'DISABLED':x.active?'ACTIVE':'INACTIVE'}</span></td><td>${x.dynamic?'Dynamic':'Static'}</td></tr>`).join('')||'<tr><td colspan="7" class="notice">Tidak ada route.</td></tr>'}catch(e){rows.innerHTML='<tr><td colspan="7" class="notice">Gagal mengambil data: '+esc(e.message)+'</td></tr>'}finally{updated.textContent='Update '+new Date().toLocaleTimeString('id-ID');refresh.disabled=false}}refresh.onclick=load;load();setInterval(load,10000);</script><script src="../assets/js/app.js?v=6"></script></body></html>